#include <bits/stdc++.h>
using namespace std;

static int par[200005];

static inline int gc() {
    static char buf[1 << 16];
    static int len = 0, pos = 0;
    if (pos == len) {
        len = (int)fread(buf, 1, sizeof(buf), stdin);
        pos = 0;
        if (len <= 0) return -1;
    }
    return buf[pos++];
}

static inline int readInt() {
    int c = gc();
    while (c != -1 && (c < '0' || c > '9')) c = gc();
    int x = 0;
    while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = gc(); }
    return x;
}

static int findp(int x) {
    int r = x;
    while (par[r] != r) r = par[r];
    while (par[x] != r) { int nx = par[x]; par[x] = r; x = nx; }
    return r;
}

int main() {
    int n = readInt(), m = readInt();
    vector<int> deg(n + 2, 0);
    vector<int> ex(m), ey(m);
    for (int i = 1; i <= n; i++) par[i] = i;
    for (int i = 0; i < m; i++) {
        int x = readInt(), y = readInt();
        ex[i] = x; ey[i] = y;
        deg[x]++; deg[y]++;
        int a = findp(x), b = findp(y);
        if (a != b) par[a] = b;
    }
    // CSR adjacency
    vector<int> start(n + 2, 0);
    for (int v = 1; v <= n; v++) start[v + 1] = start[v] + deg[v];
    vector<int> to(2 * (size_t)m);
    {
        vector<int> fill(n + 1);
        for (int v = 1; v <= n; v++) fill[v] = start[v];
        for (int i = 0; i < m; i++) {
            to[fill[ex[i]]++] = ey[i];
            to[fill[ey[i]]++] = ex[i];
        }
    }
    // Group vertices by component root (counting sort by root)
    vector<int> root(n + 1), cnt(n + 2, 0);
    for (int v = 1; v <= n; v++) { root[v] = findp(v); cnt[root[v]]++; }
    vector<int> cstart(n + 2, 0);
    for (int r = 1; r <= n; r++) cstart[r + 1] = cstart[r] + cnt[r];
    vector<int> members(n);
    {
        vector<int> fill(n + 1);
        for (int r = 1; r <= n; r++) fill[r] = cstart[r];
        for (int v = 1; v <= n; v++) members[fill[root[v]]++] = v;
    }
    vector<int> stamp(n + 1, 0);
    int cur = 0;
    for (int r = 1; r <= n; r++) {
        int lo = cstart[r], hi = cstart[r + 1];
        int s = hi - lo;
        if (s == 0) continue;
        int u = members[lo];
        for (int i = lo; i < hi; i++) {
            int v = members[i];
            if (deg[v] < deg[u]) u = v;
        }
        // all edges are inside the component, so deg <= s-1 always;
        // if the minimum degree equals s-1, every vertex has degree s-1 -> complete graph
        if (deg[u] == s - 1) continue;
        ++cur;
        for (int e = start[u]; e < start[u + 1]; e++) stamp[to[e]] = cur;
        for (int i = lo; i < hi; i++) {
            int v = members[i];
            if (v != u && stamp[v] != cur) {
                printf("%d %d\n", u, v);
                return 0;
            }
        }
    }
    printf("-1\n");
    return 0;
}
